  await Promise.all(roomJobs);ids.forEach(id=>roomsSnap.forEach(room=>{updates['roomMembers/'+room.key+'/'+id]=null}));await db.ref().update(updates);ids.forEach(id=>selectedAccountIds.delete(id));addAdminLog('Menonaktifkan '+ids.length+' akun pengguna');showToast(ids.length+' akun berhasil dinonaktifkan.');await refreshAdminPanel();
