async function refreshAdminPanel(){if(!isAdmin())return;const base='rooms/'+currentRoomId;const [accountsSnap,usersSnap,presenceSnap,messagesSnap,bannedSnap]=await Promise.all([db.ref('appConfig/accounts').once('value'),db.ref(base+'/users').once('value'),db.ref(base+'/presence').once('value'),db.ref(base+'/messages').once('value'),db.ref(base+'/bannedUsers').once('value')]);const banned=bannedSnap.val()||{},onlineIds=new Set(),roomUsers=usersSnap.val()||{},accounts=new Map();presenceSnap.forEach(x=>{const v=x.val();if(v?.userId)onlineIds.add(v.userId)});accountsSnap.forEach(x=>{const data=x.val()||{};if(data.status!=='approved')return;accounts.set(x.key,{...data,name:data.username||data.name||x.key})});usersSnap.forEach(x=>{const data=x.val()||{},existing=accounts.get(x.key)||{};accounts.set(x.key,{...data,...existing,name:existing.username||existing.name||data.name||x.key})});adminAccountRows=[...accounts.entries()].map(([id,data])=>({id,data,name:data.username||data.name||id,online:onlineIds.has(id),blocked:!!banned[id],inRoom:!!roomUsers[id]})).sort((a,b)=>safeText(a.name).localeCompare(safeText(b.name),'id'));selectedAccountIds.forEach(id=>{if(!accounts.has(id))selectedAccountIds.delete(id)});$('adminOnlineStat').textContent=onlineIds.size;$('adminUsersStat').textContent=accounts.size;$('adminMessagesStat').textContent=messagesSnap.numChildren();renderAdminUsers();renderPendingAccounts(accountsSnap);await refreshRoomsAdmin();applyRoomSettings()}
