async function addRoom(){if(!isAdmin())return;const name=$('newRoomName').value.trim(),code=$('newRoomCode').value.trim();if(name.length<2)return showToast('Nama room minimal 2 karakter.');if(code.length<4)return showToast('Kode room minimal 4 karakter.');const codeHash=await sha256(code),rooms=await db.ref('appConfig/rooms').once('value');let duplicate=false;rooms.forEach(x=>{if(x.val()?.codeHash===codeHash)duplicate=true});if(duplicate)return showToast('Kode itu sudah dipakai room lain.');const id='room_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7);await db.ref('appConfig/rooms/'+id).set({name:name.slice(0,40),codeHash,active:true,createdBy:user.name,createdAt:firebase.database.ServerValue.TIMESTAMP});$('newRoomName').value='';$('newRoomCode').value='';addAdminLog('Menambah room '+name);showToast('Room baru berhasil ditambahkan.');refreshRoomsAdmin()}
