async function deleteRoom(id,name){if(!isAdmin()||id===DEFAULT_ROOM_ID)return showToast('Ruang Umum tidak dapat dihapus.');if(id===currentRoomId)return showToast('Pindah ke room lain sebelum menghapus room ini.');if(!confirm('Hapus room '+safeText(name)+' beserta seluruh chat di room ini?'))return;const typed=prompt('Ketik nama room untuk konfirmasi: '+safeText(name));if(typed!==safeText(name))return showToast('Konfirmasi nama room tidak cocok.');const updates={};updates['appConfig/rooms/'+id]=null;updates['rooms/'+id]=null;await db.ref().update(updates);addAdminLog('Menghapus room '+safeText(name));showToast('Room dan seluruh chatnya berhasil dihapus. Akun pengguna tetap aman.');await refreshRoomsAdmin()}
function subscribeRoomInboxes(snap){clearRoomInboxListeners();const activeRoomIds=new Set();snap.forEach(child=>{const room=child.val()||{},roomId=child.key;if(room.active===false||(!isAdmin()&&roomId!==currentRoomId))return;activeRoomIds.add(roomId);if(!roomLastRead[roomId])roomLastRead[roomId]=Date.now();const query=db.ref(`rooms/${roomId}/messages`).orderByChild('timestamp').limitToLast(150),handler=messageSnap=>{const isOpen=roomId===currentRoomId&&currentView.type==='public',previous=Number(unreadRooms[roomId]||0);let unread=0,latestIncoming=null;messageSnap.forEach(message=>{const value=message.val()||{},senderId=value.senderId||value.userId;if(Number(value.timestamp||0)>roomLastRead[roomId]&&senderId!==currentAccountId()){unread++;latestIncoming=value}});unreadRooms[roomId]=isOpen?0:unread;if(isOpen)roomLastRead[roomId]=Date.now();if(!isOpen&&unread>previous&&latestIncoming){notifyIncoming(latestIncoming.name,latestIncoming.type==='image'?'📷 Foto':latestIncoming.text,false);showToast(`Pesan baru di ${safeText(room.name||roomId)}`)}updateDocumentTitle();if(latestRoomsSnapshot)renderRoomSidebar(latestRoomsSnapshot)};query.on('value',handler);roomInboxCleanup.push(()=>query.off('value',handler))});Object.keys(unreadRooms).forEach(roomId=>{if(!activeRoomIds.has(roomId))delete unreadRooms[roomId]});Object.keys(roomLastRead).forEach(roomId=>{if(!activeRoomIds.has(roomId))delete roomLastRead[roomId]})}
function renderRoomSidebar(snap){const list=$('roomGroupList');if(!list)return;list.innerHTML='';snap.forEach(child=>{const room=child.val()||{};if(room.active===false||(!isAdmin()&&child.key!==currentRoomId))return;const unread=Number(unreadRooms[child.key]||0),card=document.createElement('button');card.type='button';card.className='room-card'+(child.key===currentRoomId&&currentView.type==='public'?' active':'');card.innerHTML='<div class="room-avatar">#</div><div class="room-meta"><strong></strong><small></small></div><span class="room-unread-badge hidden"></span>';card.querySelector('strong').textContent=room.name||child.key;card.querySelector('small').textContent=child.key===currentRoomId?onlineUserIds.size+' anggota online':'Buka grup chat';const badge=card.querySelector('.room-unread-badge');badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('hidden',unread===0);badge.setAttribute('aria-label',unread+' pesan belum dibaca');card.onclick=()=>switchGroupRoom(child.key,room.name||child.key,room.active!==false);list.appendChild(card)});if(!list.children.length)list.innerHTML='<div class="contact-empty">Belum ada room aktif.</div>'}
async function switchGroupRoom(id,name,active){if(id===currentRoomId)return openPublicChat();if(!active)return showToast('Room sedang nonaktif.');try{if(!isAdmin()){const code=prompt('Masukkan kode untuk room '+safeText(name)+':');if(code===null)return;const matched=await resolveRoomByCode(code.trim());if(!matched||matched.id!==id)return showToast('Kode room tidak cocok.')}if(refs.presence)await refs.presence.remove();cleanupSession();currentRoomId=id;currentRoomName=name;user.roomId=id;user.roomName=name;localStorage.setItem('nusa_chat_user',JSON.stringify(user));await startChat();closeSidebar();showToast('Berpindah ke '+safeText(name)+'.')}catch(err){showToast(err.message||'Gagal berpindah room.')}}
